//! Generated by `rust-anything app wire` from rust-anything.json; it is rewritten on every wire.

use std::process::ExitCode;

use clap::ArgMatches;

mod version;
mod notify;
mod debug;
mod counts;
mod picker;

/// `RUST_ANYTHING_UNIT_<NAME>=original` sends that unit back to the original.
fn sent_to_original(unit: &str) -> bool {
    std::env::var(format!("RUST_ANYTHING_UNIT_{unit}")).is_ok_and(|v| v == "original")
}

pub fn dispatch(command: &str, matches: &ArgMatches) -> Option<ExitCode> {
    match command {
        "version" if !sent_to_original("VERSION") => Some(version::run(command, matches)),
        "notify" if !sent_to_original("NOTIFY") => Some(notify::run(command, matches)),
        "debug" if !sent_to_original("DEBUG") => Some(debug::run(command, matches)),
        "counts" if !sent_to_original("COUNTS") => Some(counts::run(command, matches)),
        "preview" | "list" if !sent_to_original("PICKER") => Some(picker::run(command, matches)),
        _ => None,
    }
}
